#include <item/BuiltinUtilityRuntime.hpp>
void UtilityCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources,const std::vector<std::array<unsigned,4>>& expected)
{
    using namespace auriga::item;CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"utility private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-world-utility-worker").has_value(),"utility actual asynchronous worker starts");
    for(unsigned n=0;n<sources.size();++n) {
        const auto key=sources[n].grant.key;const ItemOwner owner{ItemOwnerKind::Character,61000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"utility owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;
        const auto op=[&](){return std::array<std::uint8_t,16>{0xAC,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(++serial)};};
        const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"utility commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"utility commit saves and reloads");replay=got->write->replay;state=*got->state;};
        const auto output=[&](const char* phase){for(unsigned kind=0;kind<2;++kind){auto bytes=kind ? EncodeTypedItemDetails(*catalog,state.items).value() : EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value();std::ofstream f(path+"."+std::to_string(n)+"."+phase+(kind ? ".details.hex" : ".inventory.hex"));for(auto b:bytes){auto v=std::to_integer<unsigned>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"utility actual inventory packets export");}};
        const auto relog=[&](){const auto before=state.items;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(before==state.items,"utility stack survives a new SQL owner session");};
        auto spec=sources[n].grant;spec.count=std::min(2u,catalog->Find(key)->base.maxStack);const auto units=spec.count;const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids).value());output("bag");
        BuiltinUtilityFacts facts{{key,units,255,QuestItemContext::World,false,false,true,false},0,0,21,true,false};const auto* policy=catalog->FindUsePolicy(catalog->Find(key)->base.usePolicy);while(!(policy->allowedClasses&(1u<<facts.characterClass)))++facts.characterClass;while(!(policy->allowedSexes&(1u<<facts.sex)))++facts.sex;
        const auto plan=PrepareBuiltinUtility(*catalog,state.items[0],owner,facts).value();Check(std::array<unsigned,4>{static_cast<unsigned>(plan.handler),plan.durationSeconds,plan.firstFirework,plan.lastFirework}==expected[n] && plan.consume==1,"independently mapped original utility behavior is exact");
        for(unsigned gate=0;gate<5;++gate){auto denied=facts;if(gate==0)denied.alive=false;if(gate==1)denied.use.observer=true;if(gate==2)denied.use.admittedByServer=false;if(gate==3)denied.mapIndex=0;if(gate==4)denied.use.stackUnits=units+1;Check(!PrepareBuiltinUtility(*catalog,state.items[0],owner,denied),"real source utility refuses invalid live actor and forged stack facts");}
        if(plan.handler==BuiltinQuestItem::CourageCombined){auto denied=facts;denied.mapIndex=1;Check(!PrepareBuiltinUtility(*catalog,state.items[0],owner,denied),"real source courage map restriction enforced");}
        if(plan.handler==BuiltinQuestItem::ChinaFirework || plan.handler==BuiltinQuestItem::SpinningTop){auto denied=facts;denied.use.context=QuestItemContext::Arena;Check(!PrepareBuiltinUtility(*catalog,state.items[0],owner,denied),"real regional fireworks arena restriction enforced");denied=facts;denied.pvpPotionsBlocked=true;Check(!PrepareBuiltinUtility(*catalog,state.items[0],owner,denied),"real regional fireworks source PvP policy enforced");}
        const auto use=MakeBuiltinUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,ids[0],facts).value();apply(use);Check(units==1 ? state.items.empty() : state.items.size()==1 && state.items[0].count==1,"actual utility consumes exactly one saved unit");output("used");const auto saved=state.items;apply(use);Check(replay && state.items==saved,"utility receipt replay cannot consume twice");relog();output("relogged");facts.use.stackUnits=1;auto finalId=ids[0];if(units==1){const auto fresh=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,fresh).value());finalId=fresh[0];}
        const auto last=MakeBuiltinUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,finalId,facts).value();apply(last);Check(state.items.empty(),"last utility use removes the source instance");output("empty");apply(last);Check(replay && state.items.empty(),"last-use replay cannot resurrect the source");relog();output("empty_relogged");
    }
    store.Stop();std::cout<<"SOURCE_UTILITY_WORKER=SUCCESS sources="<<sources.size()<<" checks="<<checks<<std::endl;
}
